style.css:
@-moz-document domain("roblox.com") {
/* Apply seashell pink to all text */
    body, 
    body * {
        color: #FFF5EE !important; /* seashell pink */
    }

    /* Optional: make links a slightly stronger pink for visibility */
    a, a:visited {
        color: #ffb6c1 !important; /* light pink links */
    }

    a:hover {
        color: #ff69b4 !important; /* hot pink hover */
    }
}
